=== style.css (shared) ===
/* Mine's shared base: everything used by more than one app.
 *
 * The tokens, the form primitives, and the chrome every app builds its screens out of - icon
 * buttons, the three overlay mechanisms, the settings row, the logs panel and a rendered
 * markdown body. An app's own stylesheet loads after this one and holds only what is its own.
 *
 * The tile screen's presentation is not in here: it is one app among the others and its rules
 * live in home.css, which only the root index.html loads. A full-width filled button is a
 * choice the tile screen makes, and every app page had to undo it.
 */

:root {
  --bg: #fff; --fg: #1f2933; --muted: #6b7280; --line: #e4e7eb;
  --accent: #1f2933; --bad: #c0392b; --good: #0a7b3e; --soft: #f5f7fa;
  /* The one blue: a link, and a rendered body's links. An app that highlights something of its
     own - the calendar's today - names that colour itself. */
  --link: #1f66d0;
}
/* Mine's theme setting is "system" by default, so the device decides; light and dark are the
   two overrides, and the attribute is what carries them. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --bg: #15191e; --fg: #e8eaed; --muted: #9aa5b1; --line: #2b3138;
    --accent: #e8eaed; --bad: #ff8a7a; --good: #5bd48b; --soft: #1d2229; --link: #6ea8ff; }
}
:root[data-theme="dark"] { --bg: #15191e; --fg: #e8eaed; --muted: #9aa5b1; --line: #2b3138;
    --accent: #e8eaed; --bad: #ff8a7a; --good: #5bd48b; --soft: #1d2229; --link: #6ea8ff; }

/* An id or class rule for display beats the UA stylesheet's [hidden], so a screen and a modal
   would both render while still carrying the attribute. */
[hidden] { display: none !important; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font: 16px/1.5 system-ui, -apple-system, sans-serif;
  color: var(--fg); background: var(--bg);
}
header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
h1 { font-size: 1.4rem; margin: .2rem 0 .6rem; }
.lede { color: var(--muted); margin-top: 0; }

/* ---- form primitives ---- */

label { display: block; margin: .9rem 0; font-size: .85rem; color: var(--muted); }
input {
  display: block; width: 100%; margin-top: .3rem; padding: .75rem;
  font: inherit; color: var(--fg); background: var(--bg);
  border: 1px solid var(--line); border-radius: .5rem;
}
select {
  display: block; width: 100%; margin-top: .3rem; padding: .7rem; font: inherit;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
}
/* Neutral: a button carries the page's own type and nothing else, and every class below says
   what it looks like. The tile screen's filled, full-width button is in home.css. */
button {
  margin: 0; padding: 0; font: inherit; font-weight: 600; cursor: pointer;
  color: var(--fg); background: none; border: 0; border-radius: .6rem;
}
button[disabled] { opacity: .5; }
button.danger { color: var(--bad); background: none; border: 1px solid var(--line); }

.status, .msg { font-size: .85rem; color: var(--muted); }
.bad { color: var(--bad); }

/* ---- icon buttons ---- */
.ib {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  width: 2.1rem; height: 2.1rem; margin: 0; padding: 0;
  color: var(--fg); background: none; border: 0; border-radius: .45rem; cursor: pointer;
}
.ib svg { width: 1.05rem; height: 1.05rem; display: block; }
.ib .glyph { font-size: .9rem; font-weight: 700; line-height: 1; }
.ib[disabled] { opacity: .3; }
/* An icon whose field is set reads as enabled: darker in light mode, brighter in dark. */
.ib.on { color: var(--bg); background: var(--accent); }
/* A save is a green disk and a trashcan is a red trashcan - both glyphs on no background.
   Nothing in Mine is a filled green button. */
.ib.save { color: var(--good); }
.ib.bad { color: var(--bad); }
.ib.next svg { transform: rotate(180deg); }

/* ---- overlays ---- */
/* Two mechanisms and no third. `.pop` is a dropdown positioned under the button that opened it
   by openPop(). Everything else carries `.centred`: a preview, a field's own popup and a
   settings panel, each reached with either thumb and none of them pretending to be a drawer
   that can be dragged. */
.scrim { position: fixed; inset: 0; z-index: 8; background: rgb(0 0 0 / .35); }
.scrim.sub-scrim { z-index: 13; }
.pop {
  position: fixed; z-index: 10; width: min(20rem, calc(100vw - 1.5rem));
  padding: .7rem; background: var(--bg);
  border: 1px solid var(--line); border-radius: .7rem; box-shadow: 0 8px 30px rgb(0 0 0 / .25);
}
.pop-head { display: flex; align-items: center; gap: .3rem; margin-bottom: .4rem; }
.pop-head h2 { margin: 0; font-size: 1rem; }
.pop-head .spacer { flex: 1; }
.pop-title { width: auto; margin: 0; padding: .3rem .4rem; font-weight: 600; color: var(--fg); background: none; border: 0; }
.link { width: auto; margin: 0; padding: .25rem .4rem; font-size: .78rem; font-weight: 500; color: var(--link); background: none; border: 0; }
.link.bad { color: var(--bad); }
.link:disabled { color: var(--muted); opacity: .5; cursor: default; }

.centred {
  position: fixed; inset: 50% auto auto 50%; transform: translate(-50%, -50%);
  max-height: 86dvh; overflow-y: auto;
}
/* A panel brings its own width and padding; the rest it takes from .centred. */
.panel {
  z-index: 11; width: min(30rem, calc(100vw - 1.5rem)); padding: .8rem 1rem 1rem;
  background: var(--bg); border-radius: .9rem; box-shadow: 0 8px 30px rgb(0 0 0 / .3);
}

/* A modal opens in the middle of the screen, on a phone as much as on a desktop. */
.modal {
  position: fixed; inset: 0; z-index: 12; display: flex; align-items: center; justify-content: center;
  background: rgb(0 0 0 / .4); overflow-y: auto; overscroll-behavior: contain;
}
.card {
  width: min(32rem, calc(100% - 1.5rem)); max-height: 92dvh; overflow-y: auto;
  padding: .7rem 1rem 1rem;
  background: var(--bg); border-radius: .9rem;
}
.card label { margin: .7rem 0 0; }
.card small { display: block; margin-top: .25rem; font-size: .7rem; color: var(--muted); }

/* A row in a menu: an icon and the name of the errand behind it. */
.mrow {
  display: flex; align-items: center; gap: .55rem;
  width: 100%; margin: 0; padding: .6rem .5rem;
  font-size: .9rem; font-weight: 500; text-align: left;
  color: var(--fg); background: none; border: 0; border-radius: .45rem; cursor: pointer;
}
.mrow:hover { background: var(--soft); }
.mrow svg { flex: none; width: 1.05rem; height: 1.05rem; }

/* ---- settings rows ---- */
/* Every row is two halves: the label in the left, its control in the right. A grid rather than
   a flex row, so the controls' left edges agree down the whole panel however long a label is -
   which is the one thing a panel where each control began where its label ended did not do.
   The suffix shares the right half with its control. */
.srow {
  display: grid; grid-template-columns: 1fr 1fr; align-items: center;
  gap: .3rem .6rem; padding: .5rem 0; border-top: 1px solid var(--line);
}
.slab { font-size: .85rem; }
.srow > :nth-child(2) { justify-self: start; width: 100%; }
.sval { display: flex; align-items: center; gap: .4rem; }
.sval input { flex: 1; min-width: 0; }
.ssuf { flex: none; font-size: .75rem; color: var(--muted); }
.srow select, .srow input { width: 100%; min-width: 0; margin: 0; padding: .45rem; }
.srow input[type="checkbox"] { width: 1.2rem; height: 1.2rem; }
.srow .link { padding: .45rem 0; text-align: left; }

/* ---- the logs ---- */
/* The state line takes the settings' two-half row, so `push now` and `discard all` sit in the
   same column every other control in a panel does. Everything under it is read, not operated:
   one line per queued change, the path allowed to wrap rather than pushing the panel sideways. */
.sval.end { justify-content: flex-end; gap: .2rem; }
.lhead {
  margin: .9rem 0 .2rem; font-size: .7rem; font-weight: 600; color: var(--muted);
  text-transform: uppercase; letter-spacing: .04em;
}
.lline { margin: .1rem 0; font-size: .85rem; font-weight: 600; }
.lnote { margin: .1rem 0; font-size: .75rem; color: var(--muted); overflow-wrap: anywhere; }
.lrow {
  display: grid; grid-template-columns: 2.2rem 1fr auto; align-items: baseline;
  gap: .4rem; padding: .3rem 0; border-top: 1px solid var(--line); font-size: .75rem;
}
.lop { font-weight: 600; color: var(--muted); text-transform: uppercase; font-size: .65rem; }
.lop.del { color: var(--bad); }
.lpath { min-width: 0; overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
.lage { color: var(--muted); font-variant-numeric: tabular-nums; }

/* ---- a rendered markdown body ---- */
/* One renderer for every app in Mine, so one set of rules for what it returns: a body that
   looked right in the calendar and wrong in the diary would be the plainest sign that these
   files are not as portable as the whole idea claims.
   `#` is an h3: a body must not out-shout the title it belongs to. A paragraph keeps its own
   newlines, because a body typed as lines is read as lines. */
.md-h { margin: .8rem 0 .3rem; font-size: 1rem; line-height: 1.3; }
.md-h:first-child { margin-top: 0; }
.md-p { margin: .4rem 0; font-size: .9rem; line-height: 1.5; white-space: pre-wrap; }
.md-list { margin: .4rem 0; padding-left: 1.3rem; font-size: .9rem; line-height: 1.5; }
.md-list li { margin: .15rem 0; }
/* Rendered, not operated: ticking a box is an edit of the text like any other. */
.md-task { list-style: none; margin-left: -1.3rem; }
.md-task input { width: auto; margin: 0 .45rem 0 0; vertical-align: -.1em; }
.md-code {
  padding: .05rem .25rem; font: .85em ui-monospace, SFMono-Regular, Menlo, monospace;
  background: var(--soft); border-radius: .25rem;
}
.md-a { color: var(--link); }

/* ---- the discard prompt ---- */
/* Above the popup it is asking about, because it is asking about the popup. */
.ask { z-index: 16; }
.ask .card { width: min(20rem, calc(100% - 1.5rem)); padding: 1rem; }
.ask-q { margin: 0 0 .6rem; font-size: .95rem; font-weight: 600; }
.ask-never { display: flex; align-items: center; gap: .45rem; margin: 0; font-size: .8rem; }
.ask-never input { width: auto; margin: 0; }
.askrow { display: flex; gap: .5rem; margin-top: .9rem; }
.askrow button { flex: 1; margin: 0; padding: .6rem .4rem; font-size: .85rem; }
.askrow .ghost { color: var(--fg); background: none; border: 1px solid var(--line); }

/* ---- desktop ---- */
@media (min-width: 600px) {
  .card { max-height: 88dvh; }
  .panel { max-height: 88dvh; }
}

=== calendar/style.css ===
/* Calendar. Phone first: the desktop grid is the enhancement, not the other way round. Every
   view shows seven columns beginning with the configured first day of the week, and a month
   cell carries titled lines rather than dots - a Saturday task has to be readable.

   Loaded after ../style.css, which carries everything shared with the other apps: the tokens,
   the form primitives, the icon button, the three overlay mechanisms, the settings row, the
   logs panel and a rendered markdown body. Only what is the calendar's own is in here. */

:root { --cell: 3.3rem; --today: #1f66d0; --hour: 2.4rem; --gutter: 2rem; --tcol: 3rem; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --today: #6ea8ff; } }
:root[data-theme="dark"] { --today: #6ea8ff; }

body { padding-bottom: env(safe-area-inset-bottom); }
#cal { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }

/* ---- top pane ---- */
/* Three groups: the two view controls left, the period centred, the two ways out right. The
   centre is centred on the pane rather than on what is left over, which is what the two equal
   side tracks buy. Everything in it is drawn at twice the size it was - this is the row reached
   for on every visit, and it was the smallest thing on the screen. */
.topbar {
  position: sticky; top: 0; z-index: 5;
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: .3rem;
  padding: max(.5rem, env(safe-area-inset-top)) .5rem .5rem;
  background: var(--bg); border-bottom: 1px solid var(--line);
}
.tb-side { display: flex; align-items: center; gap: .3rem; min-width: 0; }
.tb-side.end { justify-content: flex-end; }
.tb-mid { display: flex; align-items: center; gap: .1rem; min-width: 0; }
/* The period label is a button with nothing drawn on it, so hover and press are what say it is
   one - the same affordance the year view's month caption uses. */
.period:hover { background: var(--soft); }
.period:active { background: var(--line); }
.nav {
  display: inline-flex; align-items: center; justify-content: center;
  width: auto; min-width: 2.6rem; min-height: 2.6rem; margin: 0; padding: .3rem .45rem;
  font-size: 2rem; line-height: 1; font-weight: 500; text-decoration: none;
  color: var(--fg); background: var(--soft); border: 0; border-radius: .5rem;
}
.nav.ic svg { width: 1.8rem; height: 1.8rem; display: block; }

/* A week or sprint label is long - "Sprint 7 - 02.11.2026 - 15.11.2026" is wider than a narrow
   phone on its own - so the label shrinks and ellipsises rather than pushing the page sideways.
   The dropdown still shows the period in full. */
.period {
  display: inline-flex; align-items: center; justify-content: center; min-width: 0;
  width: auto; margin: 0; padding: .4rem .4rem; font-size: 1.5rem; font-weight: 600;
  color: var(--fg); background: none; border: 0; border-radius: .5rem;
  white-space: nowrap; cursor: pointer;
}
#period-label { overflow: hidden; text-overflow: ellipsis; }

.view { flex: 1; min-height: 0; }
/* The line reports and is pressed. Nothing is drawn on it, so hover and press are what say it
   is a button - the same affordance the period label uses. `.bad` needs the second class to beat
   this rule's own colour, which the plain `.bad` in the Mine stylesheet is now behind. */
.sync {
  width: 100%; padding: .4rem .7rem; margin: 0; font: inherit; font-size: .75rem;
  text-align: left; color: inherit; background: none; border: 0; border-radius: .4rem;
  cursor: pointer;
}
.sync:hover { background: var(--soft); }
.sync:active { background: var(--line); }
.sync.bad { color: var(--bad); }

/* ---- month ---- */
.weekhead {
  display: grid; grid-template-columns: repeat(7, 1fr);
  padding: .35rem .25rem 0; font-size: .7rem; font-weight: 600;
  color: var(--muted); text-align: center; text-transform: uppercase; letter-spacing: .04em;
}
.weekhead.gut, .grid.gut { grid-template-columns: var(--gutter) repeat(7, 1fr); }
.weekhead span.we { color: var(--today); }

.grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; padding: .25rem; }
/* The month fills the whole height of the window: the week rows divide what is left over
   between them equally, so the grid is as tall as the screen allows rather than as tall as its
   cells happen to need. The extra height goes to the cell, not to more lines - the cap is about
   what a glance can read and stays four on a desktop, two on a phone. */
.view.vM { display: flex; flex-direction: column; }
.vM .grid { flex: 1; min-height: 0; grid-auto-rows: 1fr; }
/* The week number, separated from the days by a thin vertical rule. Always ISO. */
.wk {
  display: flex; align-items: center; justify-content: center;
  font-size: .6rem; font-variant-numeric: tabular-nums; color: var(--muted);
  border-right: 1px solid var(--line);
}
.day {
  display: flex; flex-direction: column; align-items: stretch; gap: .1rem;
  min-width: 0; min-height: var(--cell); padding: .15rem .12rem;
  text-align: left; color: var(--fg); background: var(--bg); border-radius: .3rem; cursor: pointer;
}
.day.we { background: var(--soft); }
.day.out { opacity: .4; }
.num {
  align-self: center; min-width: 1.5rem; padding: .1rem 0;
  font-size: .76rem; font-variant-numeric: tabular-nums; text-align: center;
  color: var(--muted); border-radius: 999px;
}
.day.today .num { color: #fff; background: var(--today); font-weight: 700; }

.rows { display: flex; flex-direction: column; gap: 1px; overflow: hidden; }
.eline {
  display: flex; align-items: center; gap: .2rem;
  padding: .06rem .22rem; font-size: .66rem; line-height: 1.3;
  border-radius: .22rem; cursor: pointer;
}
.eline .when { flex: none; font-variant-numeric: tabular-nums; opacity: .8; }
.eline .what { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* In a month cell the title is clipped rather than ellipsised: three dots cost three characters
   in the one place in the app where characters are scarcest, and a clipped word already says
   there is more. */
.grid .eline .what { text-overflow: clip; }
.eline.done .what { text-decoration: line-through; opacity: .75; }
/* A day an entry only passes through: flat on the side it continues, so a run of cells reads as
   one bar with two rounded ends. */
.eline.from-before { border-top-left-radius: 0; border-bottom-left-radius: 0; }
.eline.goes-on { border-top-right-radius: 0; border-bottom-right-radius: 0; }
.more { font-size: .6rem; color: var(--muted); padding-left: .2rem; }

/* The rectangular icon that moves a task straight to done. */
.tick {
  flex: none; width: .95rem; height: .72rem; margin: 0; padding: 0;
  background: none; border: 1.5px solid currentColor; border-radius: 2px;
  opacity: .75; cursor: pointer;
}
.tick.on { background: currentColor; opacity: 1; }

/* ---- year ---- */
/* At most six months to a row, so a year reads as two even rows rather than as ten and then
   two - and the five gaps have to come out of the share, or six tracks plus five gaps are wider
   than the container and auto-fill settles for five. */
.year {
  display: grid; gap: .7rem; padding: .5rem;
  grid-template-columns: repeat(auto-fill, minmax(max(10.5rem, (100% - 5 * .7rem) / 6), 1fr));
}
/* A caption that is a button: clicking it zooms into that month. The whole label is the
   target, because a day in a year grid is not finger-sized. */
.ycap {
  display: block; width: 100%; margin: 0 0 .25rem; padding: .15rem .2rem;
  font: inherit; font-size: .8rem; font-weight: 600; text-align: left;
  color: var(--fg); background: none; border: 0; border-radius: .3rem; cursor: pointer;
}
.ycap:hover { background: var(--soft); }
.ycap:active { background: var(--line); }
.ygrid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; }
.ywh { font-size: .55rem; color: var(--muted); text-align: center; text-transform: uppercase; }
.ywh.we { color: var(--today); }
.yday {
  width: auto; margin: 0; padding: .2rem 0;
  font-size: .62rem; font-variant-numeric: tabular-nums; font-weight: 500;
  color: var(--fg); background: none; border: 0; border-radius: .2rem; cursor: pointer;
}
.yday.out { visibility: hidden; }
.yday.today { outline: 2px solid var(--today); outline-offset: -2px; font-weight: 700; }

/* ---- week and day: columns are the days, rows are the 24 hours ---- */
.tg { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.tg-head, .tg-allday, .tg-body {
  display: grid; grid-template-columns: var(--tcol) repeat(var(--cols), 1fr);
}
.tg-head { border-bottom: 1px solid var(--line); }
.tcorner { font-size: .6rem; color: var(--muted); align-self: center; text-align: center; }
.tgd { padding: .3rem 0; text-align: center; cursor: pointer; }
.tgd.we { background: var(--soft); }
.tgd .dw { display: block; font-size: .62rem; color: var(--muted); text-transform: uppercase; }
.tgd .dn { display: block; font-size: .95rem; font-weight: 600; }
.tgd.today .dn { color: var(--today); }

.tg-allday { border-bottom: 1px solid var(--line); }
.adcell {
  display: flex; flex-direction: column; gap: 1px; min-height: 1.5rem; padding: 2px;
  border-left: 1px solid var(--line); cursor: pointer;
}
.adcell.we { background: var(--soft); }

.tg-body { flex: 1; min-height: 0; overflow-y: auto; }
.hours { display: grid; grid-template-rows: repeat(24, var(--hour)); }
.hr {
  font-size: .58rem; color: var(--muted); text-align: right; padding-right: .25rem;
  font-variant-numeric: tabular-nums;
}
.tcol {
  position: relative; height: calc(24 * var(--hour));
  border-left: 1px solid var(--line); cursor: pointer;
  background: repeating-linear-gradient(to bottom, var(--line) 0 1px, transparent 1px var(--hour));
}
.tcol.we { background-color: var(--soft); }
.tev {
  position: absolute; left: 2px; right: 2px; min-height: 1rem; overflow: hidden;
  padding: .1rem .3rem; font-size: .68rem; line-height: 1.25;
  border-radius: .3rem; cursor: pointer;
}
.tev .when { display: block; font-variant-numeric: tabular-nums; opacity: .85; }
.tev .what { display: block; font-weight: 600; }
.tev .meta { display: block; font-size: .62rem; opacity: .85; }
.tev.done .what { text-decoration: line-through; }
.tev .tick { position: absolute; top: .22rem; right: .22rem; }

/* ---- kanban ---- */
/* The board is capped and centred where the calendar window is as wide as the browser: a card
   is read at the width a sentence is read at, and a third of a wide monitor is mostly empty
   card. The cap is here rather than on #cal, which would narrow the pane with it. */
.kb {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: .5rem; padding: .5rem;
  max-width: 78rem; margin-inline: auto;
}
/* Stacked: the three stages one under the other, each full width, read by scrolling down. */
.kb.vert { grid-template-columns: 1fr; }
.view.vK.one { overflow: hidden; }
/* Exactly one column is visible. The strip is shifted by whole multiples of its own width, so
   it must carry neither gap nor padding - either one leaves a sliver of the next column at the
   edge of the screen. The spacing lives inside each column instead. */
.one .kb {
  grid-template-columns: repeat(3, 100%); gap: 0; padding: 0; max-width: none;
  transform: translateX(calc(var(--col) * -100%)); transition: transform .18s ease-out;
}
.one .kcol { margin: .5rem; }
.kcol {
  display: flex; flex-direction: column; gap: .4rem;
  padding: .4rem; background: var(--soft); border-radius: .6rem;
}
/* The state's name is centred on the column and carries that stage's colour; the `+` sits at the
   right, where it is the board's only way to make a task. Two equal side tracks, so the name is
   centred on the column rather than on what the `+` leaves over. */
.khead { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: .3rem; }
.kmid { display: flex; align-items: center; justify-content: center; gap: .2rem; min-width: 0; }
.kname {
  text-transform: capitalize; font-size: 1.6rem; font-weight: 700; line-height: 1.15;
  overflow: hidden; text-overflow: ellipsis;
}
/* The header's pagers are bigger and sit on a background of their own, so they cannot be read
   as a card's move buttons, which do something else entirely. `.ib` is in the base sheet now, so
   these win on order rather than losing to it - which is what makes the two sizes here the ones
   that apply. The background is set in the phone block below, where the pager fills the header;
   a disabled arrow keeps none, and that is what tells it from the one that still works. */
.knav { flex: none; width: 2.4rem; height: 2.4rem; }
.knav[disabled] { background: none; }
.knav svg { width: 1.5rem; height: 1.5rem; }
.kadd { justify-self: end; width: 2rem; height: 2rem; }
.kcards { display: flex; flex-direction: column; gap: .4rem; }
.kcard {
  display: flex; gap: .4rem; padding: .4rem;
  background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
}
.kbar { flex: none; width: 3px; border-radius: 2px; }
.kmain { flex: 1; min-width: 0; }
.ktop { display: flex; align-items: center; gap: .1rem; }
/* A marker, not a button: it is read on the card and set in the entry popup's toggle row. */
.kbang { flex: none; padding: 0 .1rem; font-size: .95rem; font-weight: 800; color: var(--bad); }
.ktitle {
  flex: 1; min-width: 0; padding: 0 .2rem; font-size: .85rem; font-weight: 600;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.kbody {
  margin: .25rem 0 0; font-size: .72rem; color: var(--muted); overflow: hidden;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
.kwhen { margin: .2rem 0 0; font-size: .64rem; color: var(--muted); }
/* The board filter's one important toggle. A card carries no chip at all any more. */
.chip {
  width: auto; margin: 0; padding: .14rem .42rem; font-size: .7rem; font-weight: 700;
  color: var(--fg); background: var(--bg);
  border: 1px solid var(--line); border-radius: .3rem; cursor: pointer;
}
.chip.on { outline: 2px solid var(--today); outline-offset: 1px; }

/* ---- the hamburger's menu ---- */
/* The filter is a dropdown, so a repo with twenty groups scrolls inside it rather than growing
   it past the screen - which is what folding the list away used to be for. */
#filter-pop { max-height: 70dvh; overflow-y: auto; }

/* ---- the date picker, the zoom, and the filter's list of groups ---- */
.pick-body { display: grid; gap: 2px; }
.pick-body.days { grid-template-columns: repeat(7, 1fr); }
.pick-body.years { grid-template-columns: repeat(3, 1fr); }
.pick-body.sprints { grid-template-columns: 1fr; }
.pick-body .wh { font-size: .62rem; color: var(--muted); text-align: center; text-transform: uppercase; }
.pk {
  width: auto; margin: 0; padding: .45rem .1rem; font-size: .8rem; font-weight: 500;
  color: var(--fg); background: none; border: 0; border-radius: .35rem;
}
.pk.wide { padding: .5rem .5rem; font-size: .78rem; text-align: left; }
.pk.out { color: var(--muted); opacity: .55; }
/* In a field's date picker: the day the field already holds, and - while the end date is
   being picked - the start date, so the day the end may not fall before is in the grid. */
.pk.sel { background: var(--accent); color: var(--bg); font-weight: 700; }
.pk.hl { box-shadow: inset 0 0 0 2px var(--accent); }
.pk.now { color: #fff; background: var(--today); font-weight: 700; }
/* The sprint today falls in: brighter than the rest in dark mode, darker in light. */
.pk.cur { background: var(--accent); color: var(--bg); }
.pk.cur.now { color: #fff; background: var(--today); }
.pick-body.years .pk { padding: .7rem .1rem; }

/* A filter that is on says so on the hamburger: a small count at its top right, one per kind
   of narrowing. */
.tb-side .nav.ic { position: relative; }
.fcount {
  position: absolute; top: 0; right: 0; min-width: .95rem; height: .95rem; padding: 0 .1rem;
  font-size: .6rem; font-weight: 700; line-height: .95rem; text-align: center;
  color: #fff; background: var(--today); border-radius: 999px;
}
/* The groups above, the stages and importance below: two kinds of narrowing, one dropdown. */
.fsep { height: 1px; margin: .4rem .2rem; background: var(--line); }
.glab .glyph { width: .85rem; font-size: .8rem; font-weight: 700; text-align: center; }
.glab { display: flex; align-items: center; gap: .55rem; padding: .45rem .3rem; font-size: .9rem; color: var(--fg); cursor: pointer; }
.glab input { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; }

/* The zoom's list: the four periods, or the board's two orientations, the current one marked. */
.zrow {
  display: flex; align-items: center; gap: .5rem; width: 100%; margin: 0;
  padding: .5rem .5rem; font: inherit; font-size: .95rem; text-transform: capitalize;
  color: var(--fg); background: none; border: 0; border-radius: .4rem; cursor: pointer;
}
.zrow:hover { background: var(--soft); }
.zrow .dot { flex: none; width: .5rem; height: .5rem; border-radius: 999px; background: none; }
.zrow.on { font-weight: 700; }
.zrow.on .dot { background: var(--today); }
.swatch { flex: none; width: .85rem; height: .85rem; border-radius: 999px; }

/* Wider than a dropdown, because it lists a day's entries rather than a grid of dates. */
#day-pop { width: min(22rem, calc(100vw - 1.5rem)); }

.day-list { display: flex; flex-direction: column; gap: .35rem; }
.day-empty { font-size: .8rem; color: var(--muted); margin: .3rem 0; }
.dentry {
  display: flex; align-items: center; gap: .6rem; width: 100%;
  padding: .55rem .5rem; text-align: left;
  color: var(--fg); background: var(--soft); border-radius: .5rem; cursor: pointer;
}
.dentry .bar { flex: none; width: 4px; align-self: stretch; border-radius: 2px; }
.dentry .mid { flex: 1; min-width: 0; }
.dentry .dt { display: block; font-size: .68rem; color: var(--muted); }
.dentry .dn { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dentry.done .dn { text-decoration: line-through; color: var(--muted); }
.dentry .tick { width: 1.4rem; height: 1.1rem; }

@media (max-width: 599px) {
  .grid .eline .when { display: none; }
  #day-pop { max-height: 80dvh; }
  /* Two rows on a phone, each filling the width. Five controls across one line left the period
     label - the one thing in the pane you read rather than aim at - no wider than the buttons
     beside it, and the arrows that step it had to be dropped to make even that fit. A second
     row buys back both: the four that go somewhere share the first, the period takes the
     second. Wrapping does it, so the pane keeps one DOM order at every width - `order` puts
     the two side groups first and gives the middle a row of its own. */
  .topbar { display: flex; flex-wrap: wrap; gap: .15rem .1rem; padding-inline: .35rem; }
  .tb-side { flex: 1 1 0; order: 1; }
  .tb-side.end { order: 2; }
  .tb-side .nav { flex: 1; min-width: 0; padding: .3rem .1rem; }
  /* The second row. The arrows take one share each and the label three, so the two are equal
     in size and the label between them is larger - the label carries a date to be read and an
     arrow carries only a direction. */
  .tb-mid { flex: 0 0 100%; order: 3; gap: .15rem; }
  .tb-mid .nav { flex: 1 1 0; min-width: 0; }
  .nav { min-width: 2.2rem; }
  .nav.ic svg { width: clamp(1.3rem, 5.2vw, 1.9rem); height: clamp(1.3rem, 5.2vw, 1.9rem); }
  /* The second row's arrows are drawn at the size of the icons on the row above: they were
     larger than everything over them, which made the row that steps the period the loudest
     thing in the pane. */
  .tb-mid .nav { font-size: clamp(1.3rem, 5.2vw, 1.9rem); }
  .period { flex: 3 1 0; padding: .3rem .1rem; font-size: clamp(1.25rem, 7vw, 2rem); }

  /* The board's pager fills the header: it is the only way to see another stage, and a small
     square in the middle of an otherwise empty row asked a thumb to aim at the narrowest part
     of it. The left track that balances the `+` on a desktop is dropped to make the room. */
  /* The pager fills the header where there is a pager: stacked there is none, so the header
     keeps the desktop's two side tracks and the name stays centred on the column. */
  .kb:not(.vert) .khead { grid-template-columns: 1fr auto; }
  .kb:not(.vert) .kpad { display: none; }
  .kmid { gap: .3rem; }
  /* Mixed from the foreground rather than taken from a token, because it has to read as
     brighter than the column's own `--soft` in the dark theme as well as the light one. */
  .knav {
    flex: 1 1 0; width: auto; height: 2.8rem;
    background: color-mix(in srgb, var(--fg) 14%, var(--soft));
  }
  .knav svg { width: 1.7rem; height: 1.7rem; }
}

/* ---- the entry popup ---- */
.iconbar {
  display: flex; align-items: center; flex-wrap: wrap; gap: .15rem;
  padding-bottom: .5rem; margin-bottom: .5rem; border-bottom: 1px solid var(--line);
}
.iconbar .spacer { flex: 1; }
/* The quick row, under the when: every small value as an icon and no names, with a chevron at
   its end that shows the names as lines beneath it. It does not wrap - six icons and the
   chevron are one line at 320px - and it carries no border of its own, the rows below having
   one each. */
.quick { padding: .5rem 0 .2rem; margin: 0; border: 0; flex-wrap: nowrap; }
.quick .more svg { transform: rotate(-90deg); }
.quick .more.open svg { transform: rotate(90deg); }

/* All-day and important on one line, each an icon and its word: a yes or no is not a field, so
   neither carries a trashcan, and neither fills a row on its own. */
.chips { gap: .45rem; }
.fchip {
  display: flex; align-items: center; gap: .4rem; margin: 0; padding: .4rem .7rem;
  font: inherit; font-size: .85rem; color: var(--fg); background: none;
  border: 1px solid var(--line); border-radius: 999px; cursor: pointer;
}
.fchip.on { background: var(--soft); border-color: var(--muted); font-weight: 600; }
.fchip .glyph { font-size: .8rem; font-weight: 700; }
.btngroup { display: flex; margin: .7rem 0 0; }
.seg {
  flex: 1; width: auto; margin: 0; padding: .55rem .4rem; font-size: .85rem; font-weight: 500;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: 0;
}
.seg:first-child { border-radius: .5rem 0 0 .5rem; }
.seg:last-child { border-radius: 0 .5rem .5rem 0; border-left: 0; }
.seg[aria-pressed="true"] { color: var(--bg); background: var(--accent); border-color: var(--accent); }
/* A repeating entry's scope pair rides in the top row beside the type marker, so it hugs its two
   words instead of spanning the card the way a pair under the title did. `.iconbar` wraps, and a
   stretching pair would push the trashcan, the disk and the x onto a second line. */
.iconbar .btngroup { margin: 0 .2rem; }
.iconbar .seg { flex: none; padding: .35rem .55rem; }
.body-in {
  display: block; width: 100%; margin-top: .3rem; padding: .7rem;
  font: .85rem/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
  resize: vertical;
}
/* A row is the icon, then the value - no field name beside it, because the name said what the
   icon already says in the one column where the value has to fit. An unset row shows the name in
   the value's place, muted, which is what an empty input does everywhere else in Mine. */
.frow {
  display: flex; align-items: center; gap: .6rem; width: 100%; margin: 0;
  min-height: 3.25rem; padding: .55rem .3rem; border-top: 1px solid var(--line);
}
.frow > svg { flex: none; width: 1.15rem; height: 1.15rem; }
/* The whole row left of its trashcan is the way in, so it is the button. */
.ftap {
  flex: 1; min-width: 0; margin: 0; padding: .1rem .2rem; font: inherit; font-size: .9rem;
  text-align: left; color: var(--fg); background: none; border: 0; border-radius: .4rem;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: pointer;
}
.ftap:hover { background: var(--soft); }
.ftap.unset { color: var(--muted); }
/* An inline row: the input takes the line the value was on, with the trashcan and the x where the
   closed row's trashcan already is. The row's min-height above is what holds its height still, and
   it is set by the tallest thing a row can hold - its trashcan and its x, which a set row already
   carries shut. Both the text a row shows shut and the input it holds open are shorter than that,
   so neither decides how tall the row is and opening one cannot change it. */
.frow.in > input {
  flex: 1; min-width: 0; height: 1.7rem; margin: 0; padding: 0 .4rem; font-size: .9rem;
}
.frow.in > input.title-in { height: 1.75rem; font-size: 1.15rem; font-weight: 600; }
/* The title row is the one with neither a trashcan nor an x: the popup's own x, which discards
   the whole edit, is a thumb's width above this line. */

/* A field's own popup, above the entry popup and carrying no scrim of its own. It holds the four
   controls that cannot be a line, so the rows that own them need not grow into one. */
.fpop { z-index: 14; max-height: 70dvh; overflow-y: auto; }
.fpop .glist { max-height: 50dvh; overflow-y: auto; }
.fpop label { margin: 0 0 .2rem; }

/* The body is the one field whose open shape still carries a line of its own, because a textarea
   cannot have its name and its buttons beside it. */
.frow.open { display: block; padding: .3rem .2rem .6rem; }
.fedit { display: block; }
/* The name on the first line, the trashcan and the x at the right of it: the way out of a row
   is in the same corner as the way out of the popup. */
.ftitle { display: flex; align-items: center; gap: .4rem; margin-bottom: .2rem;
  font-size: .72rem; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
  color: var(--muted); }
.ftitle svg { flex: none; width: 1rem; height: 1rem; }
.ftitle .spacer { flex: 1; }
/* The title row carries no icon, so it reads as the entry's name rather than as a field. */
.frow.first { border-top: 0; }
.ttap { font-size: 1.25rem; font-weight: 600; line-height: 1.25; white-space: normal; }
/* The when: two halves, each the way into the flow that sets it. They wrap rather than shrink,
   so a span whose two datings do not fit one line drops the end to a second, still at the right
   - the row is the one in the popup that may be two lines tall, and it is also the only one
   carrying twice as much as the others. */
.wtap { flex: 0 1 auto; font-size: .85rem; color: var(--muted); text-transform: capitalize; }
.wrow { flex-wrap: wrap; }
.wrow .wend { margin-left: auto; }
.wdash { flex: none; font-size: .85rem; color: var(--muted); }

/* A field's popup walking its steps: the month it is paging, the hours, and the quarters of the
   hour that was picked. The head is naming the step, so the month pages from a line of its own. */
.pnav { display: flex; align-items: center; gap: .2rem; margin-bottom: .35rem; }
.pnav .plabel { flex: 1; text-align: center; font-size: .85rem; font-weight: 600; }
.pnav-b.next svg { transform: rotate(180deg); }
.dpick { min-width: 14rem; }
.hgrid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 2px; }
.mgrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px; }
.hgrid .pk, .mgrid .pk { padding: .55rem .1rem; font-variant-numeric: tabular-nums; }
/* The body: rendered in full when the row is closed, raw markdown when it is open. */
.vbody-tap {
  display: block; width: 100%; margin: 0; padding: .3rem .2rem; font: inherit; text-align: left;
  color: var(--fg); background: none; border: 0; border-radius: .4rem; cursor: pointer;
}
.vbody-tap:hover { background: var(--soft); }

/* ---- the group manager, the one survivor of the sub-popup ---- */
.pop.sub {
  z-index: 14; width: min(24rem, calc(100vw - 1.5rem)); max-height: 84dvh;
  border-radius: .8rem;
}
.glist { display: flex; flex-direction: column; gap: .1rem; }
.gpick {
  display: flex; align-items: center; gap: .55rem; width: 100%; margin: 0;
  padding: .5rem .4rem; font-size: .88rem; font-weight: 500; text-align: left;
  color: var(--fg); background: none; border: 0; border-radius: .4rem;
}
.gpick.on { background: var(--soft); }
/* The one row of a picker that cannot be picked: a value in the file that the list cannot
   express, shown as it is written and kept until one that can is chosen. */
.gpick:disabled { color: var(--muted); cursor: default; }

/* ---- the group manager's rows ---- */
.grow { display: flex; align-items: center; gap: .5rem; padding: .25rem 0; }
.gname { flex: 1; font-size: .88rem; }
.grow .gpick { flex: 1; width: auto; }
.grow input { flex: 1; margin: 0; padding: .45rem; }
.grow input[type="color"] { flex: none; width: 2.2rem; height: 2.1rem; padding: 0; }

/* ---- desktop ---- */
@media (min-width: 600px) {
  :root { --cell: 6.4rem; --gutter: 2.4rem; --tcol: 3.4rem; --hour: 2.8rem; }
  /* No cap on #cal: the pane, the calendar window and the sync line are as wide as the browser.
     The cap is on the board alone, below, so the pane cannot change width when the view does. */
  .topbar { padding: .7rem .8rem; gap: .5rem; }
  /* About half an arrow glyph either side of the label. Three controls crammed together read as
     one control, and this is the group the pane is used through. */
  .tb-mid { gap: 1rem; }
  .period { font-size: 1.9rem; }
  .nav.ic svg { width: 2.1rem; height: 2.1rem; }
  .nav { min-width: 3rem; min-height: 3rem; }
  .weekhead { font-size: .75rem; padding: .5rem .3rem .2rem; }
  .day { padding: .22rem; }
  .num { align-self: flex-end; margin-right: .1rem; }
  .eline { font-size: .72rem; padding: .1rem .28rem; }
}

.vbody { margin-top: .5rem; padding-top: .5rem; border-top: 1px solid var(--line); }

