.khead { padding: ${t.kheadPad}; ${t.kheadExtra || ''} }
.kname {
  font-size: ${t.knameSize};
  font-weight: ${t.knameWeight};
  text-transform: ${t.knameCase};
  letter-spacing: ${t.knameTrack};
}
.kcards { gap: ${t.kcardGap}; }
.kcard {
  background: ${t.kcardBg};
  border: ${t.kcardBorder};
  border-radius: ${t.rmd};
  padding: ${t.kcardPad};
  box-shadow: ${t.kcardShadow};
  transition: box-shadow .14s ease, transform .14s ease;
}
.kbar { width: ${t.kbarW}; border-radius: 999px; background: var(--c, var(--accent)); }
.ktitle { font-size: ${t.ktitleSize}; font-weight: 600; }
.kbody { font-size: .72rem; line-height: 1.45; }
.kwhen { font-size: .64rem; ${t.capsMicro} color: var(--muted); }
.kbang { color: var(--bad); }
.day-empty { font-size: .74rem; color: var(--muted); ${t.capsMicro} padding: .2rem .3rem; }
.knav { border-radius: ${t.ibR}; }
.chip { border-radius: ${t.rsm}; }

/* ---------- overlays ---------- */
.modal { background: ${t.scrim}; }
.scrim { background: ${t.scrim}; }
.card, .panel, .pop {
  border-radius: ${t.rlg};
  border: ${t.popBorder};
  box-shadow: ${t.shadow};
}
.card { padding: ${t.cardPad}; }
.pop-head h2, #day-title, #fpop-title { font-family: ${t.display}; letter-spacing: ${t.dtrack}; }

/* ---------- the entry popup ---------- */
.iconbar { border-bottom: 1px solid var(--line); padding-bottom: .55rem; gap: .2rem; }
.frow { border-top: 1px solid var(--line); min-height: ${t.frowH}; padding: ${t.frowPad}; gap: .7rem; }
.ftap { font-size: .9rem; border-radius: ${t.rsm}; }
.ttap { font-size: ${t.titleSize}; font-weight: ${t.titleWeight}; font-family: ${t.display}; }
.wtap { font-size: .85rem; ${t.whenCase} }
.ftitle { ${t.capsMicro} font-size: .68rem; }
.fchip {
  border-radius: ${t.chipR};
  border: 1px solid var(--line);
  padding: .42rem .78rem;
  font-size: .82rem;
}
.fchip.on { background: ${t.fchipOn}; border-color: ${t.fchipOnLine}; color: ${t.fchipOnInk}; }
.seg { border-radius: 0; font-size: .82rem; }
.seg:first-child { border-radius: ${t.rsm} 0 0 ${t.rsm}; }
.seg:last-child { border-radius: 0 ${t.rsm} ${t.rsm} 0; }
.body-in, input, select { border-radius: ${t.rsm}; }
.md-p { font-size: .88rem; }
.md-h { font-family: ${t.display}; }

/* ---------- menus and pickers ---------- */
.mrow, .zrow, .gpick { border-radius: ${t.rsm}; font-size: .88rem; }
.pk { border-radius: ${t.rsm}; }
.pk.now { background: var(--today); }
.swatch { border-radius: ${t.swatchR}; }
.glab { border-radius: ${t.rsm}; font-size: .88rem; }

${t.extra || ''}
`;

