// is the single biggest change in how the icon row reads. Everything else - weight, size, cap
// style, the shape behind the icon - is CSS and lives on the theme above.

export const ICON_SETS = {
  default: {},
  outline: {
    trash:  { d: 'M3 5.2h10M6.4 5.2V3.4h3.2v1.8M4.7 5.2l.5 8.4h5.6l.5-8.4M6.8 7.6v3.4M9.2 7.6v3.4', stroke: 1.3 },
