// Shoots three views of the calendar under each of the eight themes.
//
// Nothing in the repo is touched: the theme CSS is injected into the live page with the page's
// CSP bypassed over CDP, the icon paths are rewritten in place, and the group and stage colours
// are remapped on the inline styles the app sets. The extra fixture entries are written straight
// into the local mirror in IndexedDB.
import fs from 'fs';
import { send, ev, goto, sleep, seed } from '/home/max/ws/mine/test/cdp.mjs';
import { THEMES, ICON_SETS } from './themes.mjs';
import { css } from './common.mjs';

const OUT = new URL('./out/', import.meta.url).pathname;
const REPO = '/home/max/ws/mine';
const W = 1360, H = 880, DSF = 2;

// name -> the `d` the app draws today, read out of the two icon tables so this never drifts.
const OLD = {};
for (const f of ['shared/ui.js', 'calendar/ui.js']) {
  const src = fs.readFileSync(`${REPO}/${f}`, 'utf8');
  for (const m of src.matchAll(/(\w+):\s*\{\s*d:\s*'([^']+)'/g)) OLD[m[1]] = m[2];
}

// ---- the richer fixture ----------------------------------------------------------------------
// The committed fixture has no location, no participants and almost nothing in the sprint the
// board opens on, which makes a thin popup and an empty kanban. These are the same shape of
// markdown, written into the mirror after the seed.

const today = new Date();
const Y = today.getFullYear(), M = String(today.getMonth() + 1).padStart(2, '0');
const day = d => `${Y}-${M}-${String(d).padStart(2, '0')}`;

const EXTRA = [
  { d: 18, t: '10:00', end: '11:30', title: 'Quarterly roadmap review', group: 'work',
    kind: 'event', important: true, loc: 'Studio 4, Oranienstr. 12',
    who: ['Maja', 'Tom', 'Priya'],
    body: 'Agenda\n- Q1 commitments\n- hiring plan\n- the two platform risks' },
  { d: 24, t: '09:30', end: '10:15', title: 'Design critique', group: 'work', kind: 'event' },
  { d: 25, t: '11:00', end: '12:00', title: 'Rewrite the onboarding copy', group: 'work',
    kind: 'task', stage: 'doing', important: true, body: 'Second pass on the three empty states.' },
  { d: 25, title: 'Order the new monitor arm', group: 'home', kind: 'task', stage: 'doing' },
  { d: 26, t: '15:00', end: '16:00', title: 'Migrate the sync queue', group: 'work',
    kind: 'task', stage: 'doing', body: 'Behind the flag until the retry test is green.' },
  { d: 19, title: 'Book the eye test', group: 'health', kind: 'task', stage: 'done' },
  { d: 20, t: '09:00', end: '09:30', title: 'Cancel the old insurance', group: 'home',
    kind: 'task', stage: 'done' },
  { d: 23, title: 'Draft the sprint notes', group: 'work', kind: 'task', stage: 'done' },
  { d: 27, t: '14:00', end: '15:00', title: 'Pick the venue for the offsite', group: 'work',
    kind: 'task', stage: 'todo', important: true, body: 'Three options, all within budget.' },
  { d: 16, t: '08:00', end: '08:45', title: 'Swimming', group: 'health', kind: 'event' }
];

const fileOf = (e, i) => {
  const fm = [`title: "${e.title}"`, `type: ${e.kind}`];
  fm.push(e.t ? `start: ${day(e.d)}T${e.t}:00Z` : `start: ${day(e.d)}`);
  if (e.end) fm.push(`end: ${day(e.d)}T${e.end}:00Z`);
  fm.push(`group: ${e.group}`);
  if (e.kind === 'task') fm.push(`stage: ${e.stage}`);
  if (e.important) fm.push('important: true');
  if (e.loc) fm.push(`location: "${e.loc}"`);
  if (e.who) fm.push(`participants: [${e.who.join(', ')}]`);
  return {
    path: `calendar/${Y}/${M}/${day(e.d)}-${(e.t || '0000').replace(':', '')}-x${i}.md`,
    oid: `x${i}`,
    text: `---\n${fm.join('\n')}\n---\n\n${e.body || ''}\n`
  };
};

const addExtra = () => ev(`(async () => {
  const db = await new Promise((res, rej) => {
    const r = indexedDB.open('mine', 1);
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
  await new Promise((res, rej) => {
    const t = db.transaction('files', 'readwrite');
    for (const f of ${JSON.stringify(EXTRA.map(fileOf))}) t.objectStore('files').put(f);
    t.oncomplete = res; t.onerror = () => rej(t.error);
  });
  return true;
})()`);

// ---- the skin --------------------------------------------------------------------------------
// One expression evaluated in the page: it adds the stylesheet, rewrites the icon paths, and
// remaps every inline colour the app writes - the group colour on an entry, the stage colour on
// a column name - keeping a custom property beside it so the CSS can tint with it.

const skin = (theme) => {
  const icons = {};
  for (const [name, spec] of Object.entries(ICON_SETS[theme.icons] || {}))
    if (OLD[name]) icons[OLD[name]] = spec;
  const groups = Object.fromEntries(
    Object.entries({ work: '#c0392b', home: '#27ae60', health: '#2980b9' })
      .map(([k, hex]) => [hex, theme.groups[k]]));
  const stages = Object.fromEntries(
    Object.entries({ todo: '#c0392b', doing: '#e0a500', done: '#27ae60' })
      .map(([k, hex]) => [hex, theme.stages[k]]));

  return `(() => {
  const CSS = ${JSON.stringify(css(theme))};
  const ICONS = ${JSON.stringify(icons)};
  const GROUPS = ${JSON.stringify(groups)};
  const STAGES = ${JSON.stringify(stages)};

  let tag = document.getElementById('__skin');
  if (!tag) { tag = document.createElement('style'); tag.id = '__skin'; document.head.append(tag); }
  tag.textContent = CSS;

  const hex = c => {
    const m = /^rgba?\\((\\d+),\\s*(\\d+),\\s*(\\d+)/.exec(c || '');
    if (m) return '#' + [1, 2, 3].map(i => (+m[i]).toString(16).padStart(2, '0')).join('');
    if ((c || '')[0] === '#') {
      let h = c.slice(1);
      if (h.length === 3) h = h.split('').map(x => x + x).join('');
      return '#' + h.slice(0, 6).toLowerCase();
    }
    return null;
  };
  const ink = h => {
    const [r, g, b] = [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16) / 255);
    return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.6 ? '#1b1f24' : '#fff';
  };
  const set = (e, prop, v) => { if (e.style.getPropertyValue(prop) !== v) e.style.setProperty(prop, v); };

  function paint() {
    for (const p of document.querySelectorAll('svg path')) {
      const spec = ICONS[p.getAttribute('d')];
      if (!spec) continue;
      p.setAttribute('d', spec.d);
      if (spec.stroke) {
        p.setAttribute('fill', 'none');
        p.setAttribute('stroke', 'currentColor');
        p.setAttribute('stroke-width', String(spec.stroke));
        p.removeAttribute('fill-rule');
      }
    }
    for (const e of document.querySelectorAll('[style]')) {
      const bg = hex(e.style.backgroundColor);
      if (bg) {
        const to = GROUPS[bg] || bg;
        set(e, '--c', to);
        if (to !== bg) set(e, 'background-color', to);
        if (e.style.color) set(e, 'color', ink(to));
        continue;
      }
      const fg = hex(e.style.color);
      if (fg) {
        const to = STAGES[fg] || fg;
        if (to !== fg) set(e, 'color', to);
        set(e, '--sc', to);
        const head = e.closest('.khead');
        if (head) set(head, '--sc', to);
      }
    }
  }

  paint();
  if (!window.__painting) {
    window.__painting = true;
    new MutationObserver(() => paint())
      .observe(document.documentElement, { childList: true, subtree: true });
  }
  return true;
})()`;
};

// ---- the run ---------------------------------------------------------------------------------

const shot = async name => {
  const s = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(`${OUT}${name}.png`, Buffer.from(s.data, 'base64'));
  console.log('  ' + name);
};

await send('Page.setBypassCSP', { enabled: true });
await send('Emulation.setDeviceMetricsOverride',
  { width: W, height: H, deviceScaleFactor: DSF, mobile: false });
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: 'light' }] });

await goto('/calendar/');
await seed('calendar', { 'calendar.weekStart': 1, 'calendar.popupExpanded': true,
  'mine.dateFormat': 'dd.mm.yyyy' });
await addExtra();

const RICH = `[...document.querySelectorAll('.eline')].find(l => /roadmap review/i.test(l.textContent))`;

for (const t of THEMES) {
  console.log(t.name);
  await goto('/calendar/', 1400);
  await ev(skin(t));
  await sleep(450);
  await shot(`${t.id}-1-month`);

  await ev(`${RICH}.click()`);
  await sleep(500);
  await shot(`${t.id}-2-popup`);

  await goto('/calendar/', 1400);
  await ev(skin(t));
  await ev(`document.querySelector('#board').click()`);
  await sleep(600);
  await shot(`${t.id}-3-kanban`);
}

console.log('done');
process.exit(0);

