/* Linen: warm paper rather than white. The page is off-white and the raised surfaces - a popup,
   a panel, a card - are a shade lighter than it, which is what gives an overlay its edge without
   a heavy border. Every colour is warm: there is no neutral grey anywhere in the set.
   `--link` is the one accent, a terracotta, and it is what an app highlights its own thing with
   (the calendar's today) rather than naming a second. */
:root {
  --bg: #faf7f2; --raise: #fffdfa; --fg: #2a2521; --muted: #8a7f72; --line: #e7dfd3;
  --accent: #2a2521; --bad: #a63f2e; --good: #4f6b3f; --soft: #f2ece2;
  --link: #9c5a2d;
  /* How much of an entry's own colour goes into the tint behind it and into the ink on top. A
     dark page needs more tint and a lighter ink, so the two are tokens rather than numbers. */
  --chip-bg: 14%; --chip-ink: 72%;
  --scrim: rgb(42 37 33 / .32);
  --shadow: 0 12px 34px rgb(70 48 24 / .16);
  /* Charter for the things that are read as a title, a humanist sans for everything operated. */
  --serif: Charter, "Bitstream Charter", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --sans: -apple-system, "Segoe UI", Cantarell, system-ui, "Helvetica Neue", sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, "DejaVu Sans Mono", monospace;
}
/* Mine's theme setting is "system" by default, so the device decides; light and dark are the
   two overrides, and the attribute is what carries them.
   The dark Linen is the same paper at night, not a different palette: a warm near-black with
   brown in it, paper-coloured ink, and the terracotta lifted to an amber that survives on it. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --bg: #17130f; --raise: #211b16; --fg: #ece4d8;
    --muted: #a39685; --line: #332a22; --accent: #ece4d8; --bad: #ef8a6f; --good: #94c27a;
