// Shoots the implemented Linen in both schemes, on a desktop and on a phone, against the real
// stylesheets - no injection of any kind this time.
import fs from 'fs';
import { send, ev, goto, sleep, seed } from '/home/max/ws/mine/test/cdp.mjs';

const OUT = new URL('./verify/', import.meta.url).pathname;
fs.mkdirSync(OUT, { recursive: true });

const today = new Date();
const Y = today.getFullYear(), M = String(today.getMonth() + 1).padStart(2, '0');
const day = d => `${Y}-${M}-${String(d).padStart(2, '0')}`;

const EXTRA = [
  { d: 18, t: '10:00', end: '11:30', title: 'Quarterly roadmap review', group: 'work',
    kind: 'event', important: true, loc: 'Studio 4, Oranienstr. 12',
    who: ['Maja', 'Tom', 'Priya'],
    body: 'Agenda\n- Q1 commitments\n- hiring plan\n- the two platform risks' },
  { d: 25, t: '11:00', end: '12:00', title: 'Rewrite the onboarding copy', group: 'work',
    kind: 'task', stage: 'doing', important: true, body: 'Second pass on the three empty states.' },
  { d: 25, title: 'Order the new monitor arm', group: 'home', kind: 'task', stage: 'doing' },
  { d: 26, t: '15:00', end: '16:00', title: 'Migrate the sync queue', group: 'work',
    kind: 'task', stage: 'doing', body: 'Behind the flag until the retry test is green.' },
  { d: 19, title: 'Book the eye test', group: 'health', kind: 'task', stage: 'done' },
  { d: 23, title: 'Draft the sprint notes', group: 'work', kind: 'task', stage: 'done' },
  { d: 27, t: '14:00', end: '15:00', title: 'Pick the venue for the offsite', group: 'work',
    kind: 'task', stage: 'todo', important: true, body: 'Three options, all within budget.' },
  { d: 21, title: 'File the November receipts', group: 'work', kind: 'task', stage: 'done',
    body: 'Scanned, tagged, in the drive folder.' },
  { d: 16, t: '08:00', end: '08:45', title: 'Swimming', group: 'health', kind: 'event' }
];

const fileOf = (e, i) => {
  const fm = [`title: "${e.title}"`, `type: ${e.kind}`];
  fm.push(e.t ? `start: ${day(e.d)}T${e.t}:00Z` : `start: ${day(e.d)}`);
  if (e.end) fm.push(`end: ${day(e.d)}T${e.end}:00Z`);
  fm.push(`group: ${e.group}`);
  if (e.kind === 'task') fm.push(`stage: ${e.stage}`);
  if (e.important) fm.push('important: true');
  if (e.loc) fm.push(`location: "${e.loc}"`);
  if (e.who) fm.push(`participants: [${e.who.join(', ')}]`);
  return { path: `calendar/${Y}/${M}/${day(e.d)}-${(e.t || '0000').replace(':', '')}-x${i}.md`,
    oid: `x${i}`, text: `---\n${fm.join('\n')}\n---\n\n${e.body || ''}\n` };
};

const addExtra = () => ev(`(async () => {
  const db = await new Promise((res, rej) => {
    const r = indexedDB.open('mine', 1);
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
  const all = await new Promise(res => {
    const q = db.transaction('files', 'readonly').objectStore('files').getAll();
    q.onsuccess = () => res(q.result);
  });
  await new Promise((res, rej) => {
    const t = db.transaction('files', 'readwrite');
    for (const f of all)
      if (/\\nNotes for /.test(f.text))
        t.objectStore('files').put({ ...f, text: f.text.replace(/\\nNotes for [^\\n]*\\n/, '\\n') });
    for (const f of ${JSON.stringify(EXTRA.map(fileOf))}) t.objectStore('files').put(f);
    t.oncomplete = res; t.onerror = () => rej(t.error);
  });
  return true;
})()`);

// The fixture's token is deliberately invalid, so the live sync line reports that and nothing
// here is about it.
const quiet = () => ev(`(() => {
  const s = document.querySelector('#sync');
  if (s) { s.textContent = 'in sync \\u00b7 last pushed 4 minutes ago \\u2014 tap for details';
           s.classList.remove('bad'); }
  return true; })()`);

const shot = async name => {
  const s = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(`${OUT}${name}.png`, Buffer.from(s.data, 'base64'));
  console.log('  ' + name);
};

const view = (w, h, scheme) => Promise.all([
  send('Emulation.setDeviceMetricsOverride',
    { width: w, height: h, deviceScaleFactor: 2, mobile: w < 600 }),
  send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: scheme }] })
]);

await send('Emulation.setDeviceMetricsOverride',
  { width: 1360, height: 880, deviceScaleFactor: 2, mobile: false });
await goto('/calendar/');
await seed('calendar', { 'calendar.weekStart': 1, 'calendar.popupExpanded': true,
  'mine.dateFormat': 'dd.mm.yyyy' });
await addExtra();

const RICH = `[...document.querySelectorAll('.eline')].find(l => /roadmap review/i.test(l.textContent))`;

for (const scheme of ['light', 'dark']) {
  console.log(scheme);
  await view(1360, 880, scheme);

  await goto('/calendar/', 1400); await quiet(); await shot(`${scheme}-1-month`);
  await ev(`${RICH}.click()`); await sleep(500); await shot(`${scheme}-2-popup`);

  await goto('/calendar/', 1400); await quiet();
  await ev(`document.querySelector('#board').click()`); await sleep(600);
  await shot(`${scheme}-3-kanban`);

  await goto('/calendar/', 1400); await quiet();
  await ev(`document.querySelector('#zoom-btn').click()`); await sleep(250);
  await ev(`[...document.querySelectorAll('#zoom-body .zrow')]
    .find(b => b.textContent.trim() === 'week').click()`);
  await sleep(500); await shot(`${scheme}-4-week`);

  await goto('/', 1200); await shot(`${scheme}-5-tiles`);

  // and the phone, which is the width the app is built for first
  await view(390, 844, scheme);
  await goto('/calendar/', 1400); await quiet(); await shot(`${scheme}-6-phone-month`);
  await ev(`document.querySelector('#board').click()`); await sleep(600);
  await shot(`${scheme}-7-phone-kanban`);
}

console.log('done');
process.exit(0);

input.old_string:
/* The four errand buttons are outlined rather than filled: a block of solid grey either side of
   the period label was the heaviest thing on a page made of hairlines. */
.topbar .nav.ic { background: none; border: 1px solid var(--line); }
.topbar .nav.ic:hover { background: var(--soft); }

input.new_string:
/* Nothing in the pane is filled: the four errand buttons are outlined and the two that step the
   period carry nothing at all, so the row is hairlines and the label, and the label is the
   heaviest thing in it. A filled block either side of it was the loudest thing on the page. */
.topbar .nav.ic { background: none; border: 1px solid var(--line); }
.topbar .nav.ic:hover, .tb-mid .nav:hover { background: var(--soft); }
.tb-mid .nav { background: none; }
.tb-mid .nav:active { background: var(--line); }

